import React, { useState, useEffect } from "react";

function RecipeGenerator() {
  const [darkMode, setDarkMode] = useState(false);
  const [mode, setMode] = useState("ingredients"); // "ingredients" or "name"
  const [recipeName, setRecipeName] = useState("");
  const [ingredients, setIngredients] = useState("");
  const [mealType, setMealType] = useState("Breakfast");
  const [cuisine, setCuisine] = useState("");
  const [cookingTime, setCookingTime] = useState("Less than 30 minutes");
  const [complexity, setComplexity] = useState("Beginner");
  const [recipes, setRecipes] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // Update the document's class for dark mode
    if (darkMode) {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }
  }, [darkMode]);

  // Helper function to clean text of all asterisks
  const cleanText = (text) => {
    return text.replace(/\*/g, "").trim();
  };

  const handleSubmitByName = async () => {
    if (!recipeName) {
      setError("Please enter a recipe name.");
      return;
    }
    setLoading(true);
    try {
      const response = await fetch(
        "http://localhost:5000/api/generate-by-name",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ recipeName }),
        }
      );
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      console.log("Full API Response for Name Search:", data); // Log the full response for debugging
      if (data.error) {
        throw new Error(data.error);
      }
      if (data.recipe) {
        const normalizedRecipes = Array.isArray(data.recipe)
          ? data.recipe
          : [data.recipe];
        console.log("Normalized Recipes:", normalizedRecipes);
        // Process and clean the recipes
        const processedRecipes = normalizedRecipes.map((recipe) => {
          if (typeof recipe === "string") {
            const sections = {
              title: "",
              ingredients: [],
              equipment: [],
              instructions: [],
              tips: [],
            };
            let currentSection = null;
            const lines = recipe
              .split("\n")
              .map((line) => line.trim().replace(/\r$/, ""));

            lines.forEach((line) => {
              // Clean the line of all asterisks for comparison
              const cleanedLine = cleanText(line);

              // Check if this is a section header - with or without asterisks
              if (
                /^\**(.+?)\**$/.test(cleanedLine) &&
                (cleanedLine.toLowerCase().includes("recipe title") ||
                  cleanedLine.toLowerCase().includes("ingredients") ||
                  cleanedLine.toLowerCase().includes("equipment") ||
                  cleanedLine.toLowerCase().includes("instructions") ||
                  cleanedLine.toLowerCase().includes("optional tips") ||
                  cleanedLine.toLowerCase().includes("serving or variations"))
              ) {
                if (cleanedLine.toLowerCase().includes("recipe title"))
                  currentSection = "title";
                else if (cleanedLine.toLowerCase().includes("ingredients"))
                  currentSection = "ingredients";
                else if (cleanedLine.toLowerCase().includes("equipment"))
                  currentSection = "equipment";
                else if (cleanedLine.toLowerCase().includes("instructions"))
                  currentSection = "instructions";
                else if (
                  cleanedLine.toLowerCase().includes("optional tips") ||
                  cleanedLine.toLowerCase().includes("serving or variations")
                )
                  currentSection = "tips";
                else currentSection = null;
              } else if (cleanedLine && currentSection) {
                // Handle content based on section
                if (currentSection === "title") {
                  sections.title = cleanText(line);
                } else if (
                  (currentSection === "ingredients" ||
                    currentSection === "equipment" ||
                    currentSection === "tips") &&
                  /^[-•*]/.test(line)
                ) {
                  // Clean list items of bullets and asterisks
                  sections[currentSection].push(
                    cleanText(line.replace(/^[-•*]\s*/, ""))
                  );
                } else if (
                  currentSection === "instructions" &&
                  !/^\**(.+?)\**$/.test(cleanedLine)
                ) {
                  // Add instructions, cleaned of any asterisks
                  sections.instructions.push(cleanText(line));
                }
              }
            });
            return sections;
          }
          // If recipe is already an object, clean all text fields of asterisks
          return {
            title: recipe.title ? cleanText(recipe.title) : "",
            ingredients: recipe.ingredients
              ? recipe.ingredients.map((item) => cleanText(item))
              : [],
            equipment: recipe.equipment
              ? recipe.equipment.map((item) => cleanText(item))
              : [],
            instructions: recipe.instructions
              ? cleanText(recipe.instructions)
              : "",
            tips: recipe.tips ? recipe.tips.map((item) => cleanText(item)) : [],
          };
        });
        setRecipes(processedRecipes);
        setError(null);
      } else {
        setRecipes([]);
      }
    } catch (err) {
      console.error("Error generating recipe by name:", err);
      setError(`Failed to generate recipe by name: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitByIngredients = async () => {
    if (!ingredients) {
      setError("Please enter ingredients.");
      return;
    }

    setLoading(true);
    try {
      const response = await fetch("http://localhost:5000/api/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ingredients,
          mealType,
          cuisine,
          cookingTime,
          complexity,
        }),
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      console.log("API Response by Ingredients:", data);
      if (data.error) {
        throw new Error(data.error);
      }
      if (data.recipe) {
        const normalizedRecipes = Array.isArray(data.recipe)
          ? data.recipe
          : [data.recipe];

        // Apply the same processing as in handleSubmitByName
        const processedRecipes = normalizedRecipes.map((recipe) => {
          if (typeof recipe === "string") {
            const sections = {
              title: "",
              ingredients: [],
              equipment: [],
              instructions: [],
              tips: [],
            };
            let currentSection = null;
            const lines = recipe
              .split("\n")
              .map((line) => line.trim().replace(/\r$/, ""));

            lines.forEach((line) => {
              // Clean the line of all asterisks for comparison
              const cleanedLine = cleanText(line);

              // Check if this is a section header - with or without asterisks
              if (
                /^\**(.+?)\**$/.test(cleanedLine) &&
                (cleanedLine.toLowerCase().includes("recipe title") ||
                  cleanedLine.toLowerCase().includes("ingredients") ||
                  cleanedLine.toLowerCase().includes("equipment") ||
                  cleanedLine.toLowerCase().includes("instructions") ||
                  cleanedLine.toLowerCase().includes("optional tips") ||
                  cleanedLine.toLowerCase().includes("serving or variations"))
              ) {
                if (cleanedLine.toLowerCase().includes("recipe title"))
                  currentSection = "title";
                else if (cleanedLine.toLowerCase().includes("ingredients"))
                  currentSection = "ingredients";
                else if (cleanedLine.toLowerCase().includes("equipment"))
                  currentSection = "equipment";
                else if (cleanedLine.toLowerCase().includes("instructions"))
                  currentSection = "instructions";
                else if (
                  cleanedLine.toLowerCase().includes("optional tips") ||
                  cleanedLine.toLowerCase().includes("serving or variations")
                )
                  currentSection = "tips";
                else currentSection = null;
              } else if (cleanedLine && currentSection) {
                // Handle content based on section
                if (currentSection === "title") {
                  sections.title = cleanText(line);
                } else if (
                  (currentSection === "ingredients" ||
                    currentSection === "equipment" ||
                    currentSection === "tips") &&
                  /^[-•*]/.test(line)
                ) {
                  // Clean list items of bullets and asterisks
                  sections[currentSection].push(
                    cleanText(line.replace(/^[-•*]\s*/, ""))
                  );
                } else if (
                  currentSection === "instructions" &&
                  !/^\**(.+?)\**$/.test(cleanedLine)
                ) {
                  // Add instructions, cleaned of any asterisks
                  sections.instructions.push(cleanText(line));
                }
              }
            });
            return sections;
          }
          // If recipe is already an object, clean all text fields of asterisks
          return {
            title: recipe.title ? cleanText(recipe.title) : "",
            ingredients: recipe.ingredients
              ? recipe.ingredients.map((item) => cleanText(item))
              : [],
            equipment: recipe.equipment
              ? recipe.equipment.map((item) => cleanText(item))
              : [],
            instructions: recipe.instructions
              ? cleanText(recipe.instructions)
              : "",
            tips: recipe.tips ? recipe.tips.map((item) => cleanText(item)) : [],
          };
        });

        setRecipes(processedRecipes);
      } else {
        setRecipes([]);
      }
    } catch (err) {
      console.error("Error generating recipe:", err);
      setError(`Failed to generate recipe: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = () => {
    if (mode === "name") {
      handleSubmitByName();
    } else {
      handleSubmitByIngredients();
    }
  };

  return (
    <div
      className={`min-h-screen bg-gradient-to-b ${
        darkMode ? "from-gray-900 to-gray-800" : "from-white to-gray-100"
      } flex items-center justify-center p-4 transition-colors duration-300 overflow-hidden text-gray-800 dark:text-white`}
    >
      <div className="absolute top-4 right-4 flex space-x-2">
        <button
          onClick={() => setDarkMode(!darkMode)}
          className="bg-gray-800 dark:bg-white text-white dark:text-black px-4 py-2 rounded shadow hover:opacity-80"
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-6xl h-[calc(100vh-2rem)]">
        {/* MIDDLE - Recipe Generator Panel */}
        <div className="bg-white dark:bg-gray-700 dark:text-white rounded-xl shadow-md p-6 flex flex-col h-full">
          <h2 className="text-xl font-bold text-center mb-6">
            Recipe Generator
          </h2>

          {/* Mode Switch */}
          <div className="mb-6 flex justify-center">
            <label className="flex items-center space-x-2 cursor-pointer">
              <span className="text-gray-800 dark:text-white">
                By Ingredients
              </span>
              <input
                type="checkbox"
                checked={mode === "name"}
                onChange={() =>
                  setMode(mode === "ingredients" ? "name" : "ingredients")
                }
                className="toggle-checkbox"
              />
              <span className="toggle-switch"></span>
              <span className="text-gray-800 dark:text-white">By Name</span>
            </label>
            <style>
              {`
                .toggle-checkbox {
                  display: none;
                }
                .toggle-switch {
                  width: 40px;
                  height: 20px;
                  background-color: #ccc;
                  border-radius: 10px;
                  position: relative;
                  cursor: pointer;
                  transition: background-color 0.3s;
                }
                .toggle-checkbox:checked + .toggle-switch {
                  background-color: #4b9af4;
                }
                .toggle-switch::after {
                  content: '';
                  width: 16px;
                  height: 16px;
                  background-color: white;
                  border-radius: 50%;
                  position: absolute;
                  top: 2px;
                  left: 2px;
                  transition: transform 0.3s;
                }
                .toggle-checkbox:checked + .toggle-switch::after {
                  transform: translateX(20px);
                }
              `}
            </style>
          </div>

          {/* Conditional Fields with Animation */}
          <div className="flex-grow space-y-6">
            <div
              className={`transition-all duration-500 ease-in-out transform ${
                mode === "ingredients"
                  ? "opacity-100 translate-x-0"
                  : "opacity-0 -translate-x-full hidden"
              }`}
            >
              {mode === "ingredients" && (
                <>
                  <div className="space-y-4">
                    <div>
                      <label
                        className="block font-semibold mb-1"
                        htmlFor="ingredients"
                      >
                        Ingredients
                      </label>
                      <input
                        id="ingredients"
                        type="text"
                        className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                        placeholder="e.g. tomato, potato, onion"
                        value={ingredients}
                        onChange={(e) => setIngredients(e.target.value)}
                      />
                    </div>
                    <div>
                      <label className="block font-semibold mb-1">
                        Meal Type
                      </label>
                      <select
                        className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                        value={mealType}
                        onChange={(e) => setMealType(e.target.value)}
                      >
                        <option>Breakfast</option>
                        <option>Lunch</option>
                        <option>Dinner</option>
                        <option>Snack</option>
                      </select>
                    </div>
                  </div>
                  <div className="space-y-4">
                    <div>
                      <label className="block font-semibold mb-1">
                        Cuisine Preference
                      </label>
                      <input
                        type="text"
                        className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                        placeholder="e.g. Indian, Italian"
                        value={cuisine}
                        onChange={(e) => setCuisine(e.target.value)}
                      />
                    </div>
                    <div>
                      <label className="block font-semibold mb-1">
                        Cooking Time
                      </label>
                      <select
                        className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                        value={cookingTime}
                        onChange={(e) => setCookingTime(e.target.value)}
                      >
                        <option>Less than 30 minutes</option>
                        <option>30-60 minutes</option>
                        <option>More than 1 hour</option>
                      </select>
                    </div>
                  </div>
                  <div>
                    <label className="block font-semibold mb-1">
                      Complexity
                    </label>
                    <select
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                      value={complexity}
                      onChange={(e) => setComplexity(e.target.value)}
                    >
                      <option>Beginner</option>
                      <option>Intermediate</option>
                      <option>Advanced</option>
                    </select>
                  </div>
                </>
              )}
            </div>
            <div
              className={`transition-all duration-500 ease-in-out transform ${
                mode === "name"
                  ? "opacity-100 translate-x-0"
                  : "opacity-0 translate-x-full hidden"
              }`}
            >
              {mode === "name" && (
                <div className="space-y-4">
                  <div>
                    <label
                      className="block font-semibold mb-1"
                      htmlFor="recipeName"
                    >
                      Recipe Name
                    </label>
                    <input
                      id="recipeName"
                      type="text"
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
                      placeholder="e.g. pizza"
                      value={recipeName}
                      onChange={(e) => setRecipeName(e.target.value)}
                    />
                  </div>
                </div>
              )}
            </div>
          </div>

          <button
            onClick={handleSubmit}
            className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded w-full mt-6"
            disabled={loading}
          >
            {loading ? "Generating..." : "Generate Recipe"}
          </button>
          {error && (
            <p className="text-red-500 dark:text-red-400 text-center mt-2">
              {error}
            </p>
          )}
        </div>

        {/* RIGHT - Recipe Output Panel */}
        <div className="bg-white dark:bg-gray-700 rounded-xl shadow-md p-6 flex flex-col h-[calc(100vh-2rem)]">
          <h2 className="text-xl font-bold mb-4 text-center text-gray-800 dark:text-white">
            Recipe Details
          </h2>

          <div className="flex-grow overflow-y-auto">
            {error && (
              <p className="text-red-500 dark:text-red-400 text-center mb-4">
                {error}
              </p>
            )}
            {loading && (
              <div className="flex items-center justify-center h-full flex-col">
                <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-blue-500"></div>
                <p className="mt-4 text-lg text-gray-800 dark:text-white animate-fade">
                  Recipe Loading...
                </p>
              </div>
            )}
            {recipes.length === 0 && !loading && (
              <p className="text-gray-500 dark:text-gray-300 text-center h-full flex items-center justify-center">
                No recipe yet. Use the panels to generate a recipe.
              </p>
            )}
            {recipes.length > 0 && !loading && (
              <div className="space-y-6">
                {recipes.map((recipe, index) => (
                  <div
                    key={index}
                    className="rounded-xl bg-white dark:bg-gray-800 shadow-md p-4 border dark:border-gray-700"
                  >
                    {typeof recipe === "string" ? (
                      // This section should no longer be needed since we're processing all recipes
                      <div className="text-sm space-y-2 text-gray-800 dark:text-white">
                        <p>Unable to format recipe properly.</p>
                      </div>
                    ) : (
                      <>
                        {recipe.title && (
                          <h3 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-4">
                            {recipe.title}
                          </h3>
                        )}

                        {/* Ingredients Section */}
                        {recipe.ingredients &&
                          recipe.ingredients.length > 0 && (
                            <div className="mb-4">
                              <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2">
                                Ingredients
                              </h4>
                              <ol className="list-decimal list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                                {recipe.ingredients.map((ing, i) => (
                                  <li key={i}>{ing}</li>
                                ))}
                              </ol>
                            </div>
                          )}

                        {/* Equipment Section - Now properly separated */}
                        {recipe.equipment && recipe.equipment.length > 0 && (
                          <div className="mb-4">
                            <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2">
                              Equipment
                            </h4>
                            <ul className="list-disc list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                              {recipe.equipment.map((eq, i) => (
                                <li key={i}>{eq}</li>
                              ))}
                            </ul>
                          </div>
                        )}

                        {/* Instructions Section */}
                        {recipe.instructions && (
                          <div className="mb-4">
                            <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2">
                              Instructions
                            </h4>
                            <div className="text-sm text-gray-800 dark:text-gray-200 whitespace-pre-wrap leading-relaxed">
                              {Array.isArray(recipe.instructions) ? (
                                recipe.instructions.map((step, i) => (
                                  <p key={i} className="mb-2">
                                    {step}
                                  </p>
                                ))
                              ) : (
                                <p>{recipe.instructions}</p>
                              )}
                            </div>
                          </div>
                        )}

                        {/* Tips Section */}
                        {recipe.tips && recipe.tips.length > 0 && (
                          <div>
                            <h4 className="text-lg font-bold text-center text-gray-800 dark:text-white mb-2">
                              Optional Tips & Variations
                            </h4>
                            <ol className="list-decimal list-inside space-y-1 text-gray-800 dark:text-gray-200 text-sm">
                              {recipe.tips.map((tip, i) => (
                                <li key={i}>{tip}</li>
                              ))}
                            </ol>
                          </div>
                        )}
                      </>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
      <style>
        {`
          .panel {
            box-sizing: border-box;
            min-height: 0;
            height: auto;
            display: flex;
            flex-direction: column;
          }
          @keyframes fade {
            0% { opacity: 0.5; }
            50% { opacity: 1; }
            100% { opacity: 0.5; }
          }
          .animate-fade {
            animation: fade 1.5s infinite;
          }
          /* Animation for mode switch */
          .transition-all {
            transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out;
          }
          .opacity-100 {
            opacity: 1;
          }
          .opacity-0 {
            opacity: 0;
          }
          .translate-x-0 {
            transform: translateX(0);
          }
          .translate-x-full {
            transform: translateX(100%);
          }
          .-translate-x-full {
            transform: translateX(-100%);
          }
          .hidden {
            display: none;
          }
        `}
      </style>
    </div>
  );
}

export default RecipeGenerator;
